          headers: { 
            'Content-Type': 'application/json',
            'apikey': message.apikey,
            'Authorization': 'Bearer ' + message.apikey,
            'Prefer': 'return=minimal'
          },
          body: JSON.stringify({ payload: message.data }) 
        });
      });
    ")),
      tags$style(HTML("
