                               textInput("nationality", "Nationality:", value = "")
                           ),
                           uiOutput("setup_warning"), 
                           actionButton("start_btn", "Start", class = "btn-action btn-start")
          ),

          # Selection
          conditionalPanel(condition = "output.phase == 'selection'",
                           uiOutput("dynamic_instruction"),
